changeSet.sql:
ALTER TABLE document.notices RENAME COLUMN document_id TO contract_id;
ALTER TABLE document.notices ADD COLUMN IF NOT EXISTS buyer_in TEXT;
ALTER TABLE document.notices ADD COLUMN IF NOT EXISTS seller_in TEXT;

UPDATE document.notices n
   SET buyer_in = d.buyer_in, seller_in = d.seller_in
  FROM document.contracts d
 WHERE d.id = n.contract_id;

ALTER TABLE document.notices DROP COLUMN IF EXISTS buyer_id;
ALTER TABLE document.notices DROP COLUMN IF EXISTS seller_id;
